(()=>{const added=[{"id":"daily-2026-10-10-r01-q01","module":"C++","type":"概念题","title":"wait 为什么使用 unique_lock，为什么还要谓词？","prompt":"wait 为什么使用 unique_lock，为什么还要谓词？","promptMarkdown":"wait 为什么使用 unique_lock，为什么还要谓词？","answer":["wait 需要在等待期间解锁、返回前重新加锁，因此用可解锁的 unique_lock。谓词在锁内检查共享条件，应写为循环或谓词重载，处理虚假唤醒和其他线程先取走任务。"],"pitfalls":["把 notify 当成共享状态；在析构队列时仍有线程访问。"],"follow":"有界队列与生产者关闭唤醒","answerMarkdown":"wait 需要在等待期间解锁、返回前重新加锁，因此用可解锁的 unique_lock。谓词在锁内检查共享条件，应写为循环或谓词重载，处理虚假唤醒和其他线程先取走任务。\n\n**易错点：**把 notify 当成共享状态；在析构队列时仍有线程访问。\n\n**下一轮强化：**有界队列与生产者关闭唤醒","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":1,"sourceQuestion":1,"sourceRoundTitle":"条件变量、虚假唤醒与关闭","originalQuestionHeading":"wait 为什么使用 unique_lock，为什么还要谓词？"},{"id":"daily-2026-10-10-r01-q02","module":"C++","type":"概念题","title":"notify_one 是否保证等待者醒来后一定有任务？","prompt":"notify_one 是否保证等待者醒来后一定有任务？","promptMarkdown":"notify_one 是否保证等待者醒来后一定有任务？","answer":["通知不是任务计数；线程可能虚假唤醒，或重新获取锁前任务已被其他消费者取走。正确性来自同一锁保护的状态与谓词。"],"pitfalls":["把 notify 当成共享状态；在析构队列时仍有线程访问。"],"follow":"有界队列与生产者关闭唤醒","answerMarkdown":"通知不是任务计数；线程可能虚假唤醒，或重新获取锁前任务已被其他消费者取走。正确性来自同一锁保护的状态与谓词。\n\n**易错点：**把 notify 当成共享状态；在析构队列时仍有线程访问。\n\n**下一轮强化：**有界队列与生产者关闭唤醒","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":1,"sourceQuestion":2,"sourceRoundTitle":"条件变量、虚假唤醒与关闭","originalQuestionHeading":"notify_one 是否保证等待者醒来后一定有任务？"},{"id":"daily-2026-10-10-r01-q03","module":"C++","type":"场景题","title":"队列消费者偶尔永久等待，关闭时又无法退出，如何定位？","prompt":"队列消费者偶尔永久等待，关闭时又无法退出，如何定位？","promptMarkdown":"队列消费者偶尔永久等待，关闭时又无法退出，如何定位？","answer":["检查条件修改是否持同一锁、谓词是否包含 closed、关闭是否 notify_all。止损停止接入；修复状态后再通知，关闭时唤醒全部等待者，不用 sleep 猜测。"],"pitfalls":["把 notify 当成共享状态；在析构队列时仍有线程访问。"],"follow":"有界队列与生产者关闭唤醒","answerMarkdown":"检查条件修改是否持同一锁、谓词是否包含 closed、关闭是否 notify_all。止损停止接入；修复状态后再通知，关闭时唤醒全部等待者，不用 sleep 猜测。\n\n**易错点：**把 notify 当成共享状态；在析构队列时仍有线程访问。\n\n**下一轮强化：**有界队列与生产者关闭唤醒","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":1,"sourceQuestion":3,"sourceRoundTitle":"条件变量、虚假唤醒与关闭","originalQuestionHeading":"队列消费者偶尔永久等待，关闭时又无法退出，如何定位？"},{"id":"daily-2026-10-10-r01-q04","module":"C++","type":"代码题","title":"实现可关闭阻塞队列：关闭后拒绝 push，取完已有元素后 pop 返回空。","prompt":"实现可关闭阻塞队列：关闭后拒绝 push，取完已有元素后 pop 返回空。","promptMarkdown":"实现可关闭阻塞队列：关闭后拒绝 push，取完已有元素后 pop 返回空。","answer":["见代码。返回 optional；关闭后允许排空已入队任务，只有 closed 且队列为空才返回 nullopt。"],"pitfalls":["把 notify 当成共享状态；在析构队列时仍有线程访问。"],"follow":"有界队列与生产者关闭唤醒","answerMarkdown":"见代码。返回 optional；关闭后允许排空已入队任务，只有 closed 且队列为空才返回 nullopt。\n\n**易错点：**把 notify 当成共享状态；在析构队列时仍有线程访问。\n\n```cpp\n#include <cassert>\n#include <condition_variable>\n#include <mutex>\n#include <optional>\n#include <queue>\n#include <thread>\nclass Queue {\n    std::mutex m_; std::condition_variable cv_; std::queue<int> q_; bool closed_=false;\npublic:\n    bool push(int x) {\n        { std::lock_guard<std::mutex> lock(m_); if(closed_) return false; q_.push(x); }\n        cv_.notify_one(); return true;\n    }\n    std::optional<int> pop() {\n        std::unique_lock<std::mutex> lock(m_);\n        cv_.wait(lock,[this]{return closed_ || !q_.empty();});\n        if(q_.empty()) return std::nullopt;\n        int x=q_.front(); q_.pop(); return x;\n    }\n    void close() {\n        { std::lock_guard<std::mutex> lock(m_); closed_=true; }\n        cv_.notify_all();\n    }\n};\nint main() {\n    Queue q; int sum=0;\n    std::thread t([&]{while(auto x=q.pop()) sum+=*x;});\n    assert(q.push(2)); assert(q.push(3)); q.close(); t.join();\n    assert(sum==5 && !q.push(4) && !q.pop());\n}\n```\n\n**复杂度与边界：**队列单次操作 O(1)，总存储 O(N)，等待时间另计。示例无容量限制；队列寿命必须覆盖工作线程。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**有界队列与生产者关闭唤醒","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":1,"sourceQuestion":4,"sourceRoundTitle":"条件变量、虚假唤醒与关闭","originalQuestionHeading":"实现可关闭阻塞队列：关闭后拒绝 push，取完已有元素后 pop 返回空。"},{"id":"daily-2026-10-10-r01-q05","module":"项目追问","type":"场景题","title":"IM 任务队列关闭与数据库池销毁应如何配合？","prompt":"IM 任务队列关闭与数据库池销毁应如何配合？","promptMarkdown":"IM 任务队列关闭与数据库池销毁应如何配合？","answer":["建议先拒绝新任务，唤醒工作线程并等待任务结束，再销毁数据库资源。若提前停止借出连接，已接受任务可能无法完成，应根据是否需要后续连接选择明确的排空策略。"],"pitfalls":["把 notify 当成共享状态；在析构队列时仍有线程访问。"],"follow":"有界队列与生产者关闭唤醒","answerMarkdown":"建议先拒绝新任务，唤醒工作线程并等待任务结束，再销毁数据库资源。若提前停止借出连接，已接受任务可能无法完成，应根据是否需要后续连接选择明确的排空策略。\n\n**易错点：**把 notify 当成共享状态；在析构队列时仍有线程访问。\n\n**下一轮强化：**有界队列与生产者关闭唤醒","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":1,"sourceQuestion":5,"sourceRoundTitle":"条件变量、虚假唤醒与关闭","originalQuestionHeading":"IM 任务队列关闭与数据库池销毁应如何配合？"},{"id":"daily-2026-10-10-r02-q01","module":"C++","type":"概念题","title":"volatile 能否保证多线程可见性和复合操作原子性？","prompt":"volatile 能否保证多线程可见性和复合操作原子性？","promptMarkdown":"volatile 能否保证多线程可见性和复合操作原子性？","answer":["volatile 主要约束特定访问行为，不能提供线程同步，也不能让 ++ 原子；并发冲突访问普通对象仍是数据竞争。"],"pitfalls":["原子标志不是整个对象的锁；反复发布需要新协议。"],"follow":"多字段不变量与 mutex","answerMarkdown":"volatile 主要约束特定访问行为，不能提供线程同步，也不能让 ++ 原子；并发冲突访问普通对象仍是数据竞争。\n\n**易错点：**原子标志不是整个对象的锁；反复发布需要新协议。\n\n**下一轮强化：**多字段不变量与 mutex","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":2,"sourceQuestion":1,"sourceRoundTitle":"atomic、volatile 与发布数据","originalQuestionHeading":"volatile 能否保证多线程可见性和复合操作原子性？"},{"id":"daily-2026-10-10-r02-q02","module":"C++","type":"概念题","title":"release/acquire 如何发布普通数据，relaxed 何时够用？","prompt":"release/acquire 如何发布普通数据，relaxed 何时够用？","promptMarkdown":"release/acquire 如何发布普通数据，relaxed 何时够用？","answer":["对同一原子变量，acquire 读取到 release 发布的值时形成同步关系，使发布前写入对读线程可见。只统计独立计数且不发布其他数据时可考虑 relaxed。"],"pitfalls":["原子标志不是整个对象的锁；反复发布需要新协议。"],"follow":"多字段不变量与 mutex","answerMarkdown":"对同一原子变量，acquire 读取到 release 发布的值时形成同步关系，使发布前写入对读线程可见。只统计独立计数且不发布其他数据时可考虑 relaxed。\n\n**易错点：**原子标志不是整个对象的锁；反复发布需要新协议。\n\n**下一轮强化：**多字段不变量与 mutex","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":2,"sourceQuestion":2,"sourceRoundTitle":"atomic、volatile 与发布数据","originalQuestionHeading":"release/acquire 如何发布普通数据，relaxed 何时够用？"},{"id":"daily-2026-10-10-r02-q03","module":"C++","type":"场景题","title":"ready 已设为 true，但另一线程读到未初始化配置，如何检查？","prompt":"ready 已设为 true，但另一线程读到未初始化配置，如何检查？","promptMarkdown":"ready 已设为 true，但另一线程读到未初始化配置，如何检查？","answer":["检查 ready 是否原子、内存序是否建立同步、数据是否在发布后继续无锁改写。使用线程分析和最小复现，不能凭一次运行成功推断正确。"],"pitfalls":["原子标志不是整个对象的锁；反复发布需要新协议。"],"follow":"多字段不变量与 mutex","answerMarkdown":"检查 ready 是否原子、内存序是否建立同步、数据是否在发布后继续无锁改写。使用线程分析和最小复现，不能凭一次运行成功推断正确。\n\n**易错点：**原子标志不是整个对象的锁；反复发布需要新协议。\n\n**下一轮强化：**多字段不变量与 mutex","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":2,"sourceQuestion":3,"sourceRoundTitle":"atomic、volatile 与发布数据","originalQuestionHeading":"ready 已设为 true，但另一线程读到未初始化配置，如何检查？"},{"id":"daily-2026-10-10-r02-q04","module":"C++","type":"代码题","title":"用 release/acquire 实现一次性数据发布。","prompt":"用 release/acquire 实现一次性数据发布。","promptMarkdown":"用 release/acquire 实现一次性数据发布。","answer":["见代码；发布后 data 不再修改，只有一个发布者。"],"pitfalls":["原子标志不是整个对象的锁；反复发布需要新协议。"],"follow":"多字段不变量与 mutex","answerMarkdown":"见代码；发布后 data 不再修改，只有一个发布者。\n\n**易错点：**原子标志不是整个对象的锁；反复发布需要新协议。\n\n```cpp\n#include <atomic>\n#include <cassert>\n#include <thread>\nint main() {\n    int data=0; std::atomic<bool> ready{false}; int observed=0;\n    std::thread reader([&]{\n        while(!ready.load(std::memory_order_acquire)) std::this_thread::yield();\n        observed=data;\n    });\n    data=42; ready.store(true,std::memory_order_release);\n    reader.join(); assert(observed==42);\n}\n```\n\n**复杂度与边界：**教学操作 O(1)，等待次数不定，空间 O(1)；忙等待仅用于最小例，实际工作可用条件变量。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**多字段不变量与 mutex","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":2,"sourceQuestion":4,"sourceRoundTitle":"atomic、volatile 与发布数据","originalQuestionHeading":"用 release/acquire 实现一次性数据发布。"},{"id":"daily-2026-10-10-r02-q05","module":"项目追问","type":"场景题","title":"IM 配置热更新为何不能只替换一个普通裸指针？","prompt":"IM 配置热更新为何不能只替换一个普通裸指针？","promptMarkdown":"IM 配置热更新为何不能只替换一个普通裸指针？","answer":["建议配置采用不可变快照，明确快照对象寿命；C++17 可用互斥保护 shared_ptr，或对应 shared_ptr 原子自由函数。原子替换指针也不自动保护指向对象的可变字段。"],"pitfalls":["原子标志不是整个对象的锁；反复发布需要新协议。"],"follow":"多字段不变量与 mutex","answerMarkdown":"建议配置采用不可变快照，明确快照对象寿命；C++17 可用互斥保护 shared_ptr，或对应 shared_ptr 原子自由函数。原子替换指针也不自动保护指向对象的可变字段。\n\n**易错点：**原子标志不是整个对象的锁；反复发布需要新协议。\n\n**下一轮强化：**多字段不变量与 mutex","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":2,"sourceQuestion":5,"sourceRoundTitle":"atomic、volatile 与发布数据","originalQuestionHeading":"IM 配置热更新为何不能只替换一个普通裸指针？"},{"id":"daily-2026-10-10-r03-q01","module":"C++","type":"概念题","title":"何时基类析构函数需要 virtual？","prompt":"何时基类析构函数需要 virtual？","promptMarkdown":"何时基类析构函数需要 virtual？","answer":["通过基类指针删除派生对象需要适当的虚析构，以正确析构派生部分。另一种设计是禁止通过基类删除，例如受保护非虚析构；不能任意混用。"],"pitfalls":["按值存 vector<Base> 会切片；clone 的语义也需定义。"],"follow":"异常安全与 Rule of Zero","answerMarkdown":"通过基类指针删除派生对象需要适当的虚析构，以正确析构派生部分。另一种设计是禁止通过基类删除，例如受保护非虚析构；不能任意混用。\n\n**易错点：**按值存 vector<Base> 会切片；clone 的语义也需定义。\n\n**下一轮强化：**异常安全与 Rule of Zero","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":3,"sourceQuestion":1,"sourceRoundTitle":"多态、虚析构与对象切片","originalQuestionHeading":"何时基类析构函数需要 virtual？"},{"id":"daily-2026-10-10-r03-q02","module":"C++","type":"概念题","title":"按值传递基类为什么发生对象切片？","prompt":"按值传递基类为什么发生对象切片？","promptMarkdown":"按值传递基类为什么发生对象切片？","answer":["按值复制基类只保留基类子对象，派生成员与行为丢失；引用或指针保持动态类型，拥有型复制需要 clone 等明确接口。"],"pitfalls":["按值存 vector<Base> 会切片；clone 的语义也需定义。"],"follow":"异常安全与 Rule of Zero","answerMarkdown":"按值复制基类只保留基类子对象，派生成员与行为丢失；引用或指针保持动态类型，拥有型复制需要 clone 等明确接口。\n\n**易错点：**按值存 vector<Base> 会切片；clone 的语义也需定义。\n\n**下一轮强化：**异常安全与 Rule of Zero","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":3,"sourceQuestion":2,"sourceRoundTitle":"多态、虚析构与对象切片","originalQuestionHeading":"按值传递基类为什么发生对象切片？"},{"id":"daily-2026-10-10-r03-q03","module":"C++","type":"场景题","title":"插件对象经基类指针释放后资源未关闭，如何确认根因？","prompt":"插件对象经基类指针释放后资源未关闭，如何确认根因？","promptMarkdown":"插件对象经基类指针释放后资源未关闭，如何确认根因？","answer":["核对销毁路径、析构是否虚、资源 RAII、实例所有权；使用析构日志与最小测试。修复所有权和析构契约，不只手工补调用。"],"pitfalls":["按值存 vector<Base> 会切片；clone 的语义也需定义。"],"follow":"异常安全与 Rule of Zero","answerMarkdown":"核对销毁路径、析构是否虚、资源 RAII、实例所有权；使用析构日志与最小测试。修复所有权和析构契约，不只手工补调用。\n\n**易错点：**按值存 vector<Base> 会切片；clone 的语义也需定义。\n\n**下一轮强化：**异常安全与 Rule of Zero","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":3,"sourceQuestion":3,"sourceRoundTitle":"多态、虚析构与对象切片","originalQuestionHeading":"插件对象经基类指针释放后资源未关闭，如何确认根因？"},{"id":"daily-2026-10-10-r03-q04","module":"C++","type":"代码题","title":"实现多态 clone，复制后保留派生行为。","prompt":"实现多态 clone，复制后保留派生行为。","promptMarkdown":"实现多态 clone，复制后保留派生行为。","answer":["见代码；unique_ptr 管理结果，虚 clone 在派生类复制自身。"],"pitfalls":["按值存 vector<Base> 会切片；clone 的语义也需定义。"],"follow":"异常安全与 Rule of Zero","answerMarkdown":"见代码；unique_ptr 管理结果，虚 clone 在派生类复制自身。\n\n**易错点：**按值存 vector<Base> 会切片；clone 的语义也需定义。\n\n```cpp\n#include <cassert>\n#include <memory>\nclass Base {\npublic:\n    virtual ~Base()=default;\n    virtual int value() const=0;\n    virtual std::unique_ptr<Base> clone() const=0;\n};\nclass Derived final:public Base {\n    int n_;\npublic:\n    explicit Derived(int n):n_(n){}\n    int value() const override {return n_;}\n    std::unique_ptr<Base> clone() const override {return std::make_unique<Derived>(*this);}\n};\nint main(){\n    std::unique_ptr<Base> a=std::make_unique<Derived>(7);\n    auto b=a->clone(); a.reset(); assert(b->value()==7);\n}\n```\n\n**复杂度与边界：**本例复制时间/空间 O(1)，真实类型取决于成员内容；不演示插件卸载时代码寿命。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**异常安全与 Rule of Zero","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":3,"sourceQuestion":4,"sourceRoundTitle":"多态、虚析构与对象切片","originalQuestionHeading":"实现多态 clone，复制后保留派生行为。"},{"id":"daily-2026-10-10-r03-q05","module":"项目追问","type":"场景题","title":"IM 业务处理器用继承还是组合，如何判断？","prompt":"IM 业务处理器用继承还是组合，如何判断？","promptMarkdown":"IM 业务处理器用继承还是组合，如何判断？","answer":["建议真正的可替换接口用多态；协议解析、存储、鉴权等独立能力优先组合。接口需说明线程归属、失败语义和寿命，继承不能替代这些约束。"],"pitfalls":["按值存 vector<Base> 会切片；clone 的语义也需定义。"],"follow":"异常安全与 Rule of Zero","answerMarkdown":"建议真正的可替换接口用多态；协议解析、存储、鉴权等独立能力优先组合。接口需说明线程归属、失败语义和寿命，继承不能替代这些约束。\n\n**易错点：**按值存 vector<Base> 会切片；clone 的语义也需定义。\n\n**下一轮强化：**异常安全与 Rule of Zero","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":3,"sourceQuestion":5,"sourceRoundTitle":"多态、虚析构与对象切片","originalQuestionHeading":"IM 业务处理器用继承还是组合，如何判断？"},{"id":"daily-2026-10-10-r04-q01","module":"Linux","type":"概念题","title":"fd 是资源本身还是进程内索引，为什么会复用？","prompt":"fd 是资源本身还是进程内索引，为什么会复用？","promptMarkdown":"fd 是资源本身还是进程内索引，为什么会复用？","answer":["fd 是进程文件描述符表索引，关闭后数值可重新分配；只按数值识别会把旧操作施加到新资源。"],"pitfalls":["fd 相同不等于同一连接；双重 close 可能关闭别人资源。"],"follow":"描述符所有权与优雅关闭","answerMarkdown":"fd 是进程文件描述符表索引，关闭后数值可重新分配；只按数值识别会把旧操作施加到新资源。\n\n**易错点：**fd 相同不等于同一连接；双重 close 可能关闭别人资源。\n\n**下一轮强化：**描述符所有权与优雅关闭","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":4,"sourceQuestion":1,"sourceRoundTitle":"Linux 文件描述符与重复关闭","originalQuestionHeading":"fd 是资源本身还是进程内索引，为什么会复用？"},{"id":"daily-2026-10-10-r04-q02","module":"Linux","type":"概念题","title":"dup 后两个 fd 是否有独立文件偏移？","prompt":"dup 后两个 fd 是否有独立文件偏移？","promptMarkdown":"dup 后两个 fd 是否有独立文件偏移？","answer":["dup 引用同一 open file description，通常共享文件偏移和文件状态标志；描述符自身标志如 close-on-exec 是另一层。"],"pitfalls":["fd 相同不等于同一连接；双重 close 可能关闭别人资源。"],"follow":"描述符所有权与优雅关闭","answerMarkdown":"dup 引用同一 open file description，通常共享文件偏移和文件状态标志；描述符自身标志如 close-on-exec 是另一层。\n\n**易错点：**fd 相同不等于同一连接；双重 close 可能关闭别人资源。\n\n**下一轮强化：**描述符所有权与优雅关闭","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":4,"sourceQuestion":2,"sourceRoundTitle":"Linux 文件描述符与重复关闭","originalQuestionHeading":"dup 后两个 fd 是否有独立文件偏移？"},{"id":"daily-2026-10-10-r04-q03","module":"Linux","type":"场景题","title":"旧回调 close(57) 关闭了新连接，怎样止损和修复？","prompt":"旧回调 close(57) 关闭了新连接，怎样止损和修复？","promptMarkdown":"旧回调 close(57) 关闭了新连接，怎样止损和修复？","answer":["关联 fd 分配关闭、generation 与异步任务时间；立即拒绝旧回调，根治采用唯一所有权与代际条件执行。不能把 close 再重试当成无条件安全。"],"pitfalls":["fd 相同不等于同一连接；双重 close 可能关闭别人资源。"],"follow":"描述符所有权与优雅关闭","answerMarkdown":"关联 fd 分配关闭、generation 与异步任务时间；立即拒绝旧回调，根治采用唯一所有权与代际条件执行。不能把 close 再重试当成无条件安全。\n\n**易错点：**fd 相同不等于同一连接；双重 close 可能关闭别人资源。\n\n**下一轮强化：**描述符所有权与优雅关闭","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":4,"sourceQuestion":3,"sourceRoundTitle":"Linux 文件描述符与重复关闭","originalQuestionHeading":"旧回调 close(57) 关闭了新连接，怎样止损和修复？"},{"id":"daily-2026-10-10-r04-q04","module":"Linux","type":"代码题","title":"实现单 Reactor 的 (fd,generation) 条件注销模型。","prompt":"实现单 Reactor 的 (fd,generation) 条件注销模型。","promptMarkdown":"实现单 Reactor 的 (fd,generation) 条件注销模型。","answer":["见代码，仅模拟注销，不执行操作系统 close。"],"pitfalls":["fd 相同不等于同一连接；双重 close 可能关闭别人资源。"],"follow":"描述符所有权与优雅关闭","answerMarkdown":"见代码，仅模拟注销，不执行操作系统 close。\n\n**易错点：**fd 相同不等于同一连接；双重 close 可能关闭别人资源。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <unordered_map>\nclass Table {\n    std::unordered_map<int,std::uint64_t> rows_;\npublic:\n    void add(int fd,std::uint64_t generation){rows_[fd]=generation;}\n    bool remove(int fd,std::uint64_t generation){\n        auto it=rows_.find(fd);\n        if(it==rows_.end() || it->second!=generation) return false;\n        rows_.erase(it); return true;\n    }\n};\nint main(){\n    Table t; t.add(57,1); assert(t.remove(57,1)); t.add(57,2);\n    assert(!t.remove(57,1)); assert(t.remove(57,2));\n}\n```\n\n**复杂度与边界：**期望 O(1)、最坏 O(N) 查找，存储 O(N)。单线程模型；代际分配与防回绕需另设计。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**描述符所有权与优雅关闭","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":4,"sourceQuestion":4,"sourceRoundTitle":"Linux 文件描述符与重复关闭","originalQuestionHeading":"实现单 Reactor 的 (fd,generation) 条件注销模型。"},{"id":"daily-2026-10-10-r04-q05","module":"项目追问","type":"场景题","title":"为什么连接表、事件订阅和异步任务必须共同校验代际？","prompt":"为什么连接表、事件订阅和异步任务必须共同校验代际？","promptMarkdown":"为什么连接表、事件订阅和异步任务必须共同校验代际？","answer":["建议回调返回 Reactor 后核对连接仍存在且代际相同，取消任务与注销事件后再释放资源。weak_ptr 只保证对象寿命，代际用于过滤逻辑上失效结果。"],"pitfalls":["fd 相同不等于同一连接；双重 close 可能关闭别人资源。"],"follow":"描述符所有权与优雅关闭","answerMarkdown":"建议回调返回 Reactor 后核对连接仍存在且代际相同，取消任务与注销事件后再释放资源。weak_ptr 只保证对象寿命，代际用于过滤逻辑上失效结果。\n\n**易错点：**fd 相同不等于同一连接；双重 close 可能关闭别人资源。\n\n**下一轮强化：**描述符所有权与优雅关闭","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":4,"sourceQuestion":5,"sourceRoundTitle":"Linux 文件描述符与重复关闭","originalQuestionHeading":"为什么连接表、事件订阅和异步任务必须共同校验代际？"},{"id":"daily-2026-10-10-r05-q01","module":"TCP/HTTP","type":"概念题","title":"TIME_WAIT 与 CLOSE_WAIT 分别处在哪个关闭阶段？","prompt":"TIME_WAIT 与 CLOSE_WAIT 分别处在哪个关闭阶段？","promptMarkdown":"TIME_WAIT 与 CLOSE_WAIT 分别处在哪个关闭阶段？","answer":["TIME_WAIT 通常出现在主动关闭完成后的等待阶段，用于处理旧报文与最终 ACK 重传；CLOSE_WAIT 表示收到对端 FIN 后，本地尚未完成关闭。"],"pitfalls":["FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。"],"follow":"发送背压与业务 ACK","answerMarkdown":"TIME_WAIT 通常出现在主动关闭完成后的等待阶段，用于处理旧报文与最终 ACK 重传；CLOSE_WAIT 表示收到对端 FIN 后，本地尚未完成关闭。\n\n**易错点：**FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。\n\n**下一轮强化：**发送背压与业务 ACK","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":5,"sourceQuestion":1,"sourceRoundTitle":"TIME_WAIT、CLOSE_WAIT 与半关闭","originalQuestionHeading":"TIME_WAIT 与 CLOSE_WAIT 分别处在哪个关闭阶段？"},{"id":"daily-2026-10-10-r05-q02","module":"TCP/HTTP","type":"概念题","title":"recv 返回 0 后能否继续发送？","prompt":"recv 返回 0 后能否继续发送？","promptMarkdown":"recv 返回 0 后能否继续发送？","answer":["对端关闭发送方向使本端读取 EOF，TCP 支持半关闭，本端仍可能发送。应用是否继续要依协议与超时判断。"],"pitfalls":["FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。"],"follow":"发送背压与业务 ACK","answerMarkdown":"对端关闭发送方向使本端读取 EOF，TCP 支持半关闭，本端仍可能发送。应用是否继续要依协议与超时判断。\n\n**易错点：**FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。\n\n**下一轮强化：**发送背压与业务 ACK","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":5,"sourceQuestion":2,"sourceRoundTitle":"TIME_WAIT、CLOSE_WAIT 与半关闭","originalQuestionHeading":"recv 返回 0 后能否继续发送？"},{"id":"daily-2026-10-10-r05-q03","module":"TCP/HTTP","type":"场景题","title":"节点大量 CLOSE_WAIT，同时在线人数下降，首先查什么？","prompt":"节点大量 CLOSE_WAIT，同时在线人数下降，首先查什么？","promptMarkdown":"节点大量 CLOSE_WAIT，同时在线人数下降，首先查什么？","answer":["优先查本地 EOF 分支、异常路径、引用持有和 close 是否执行，再看线程是否卡在依赖。用 ss、fd 数与连接寿命日志关联，不能先靠内核参数掩盖泄漏。"],"pitfalls":["FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。"],"follow":"发送背压与业务 ACK","answerMarkdown":"优先查本地 EOF 分支、异常路径、引用持有和 close 是否执行，再看线程是否卡在依赖。用 ss、fd 数与连接寿命日志关联，不能先靠内核参数掩盖泄漏。\n\n**易错点：**FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。\n\n**下一轮强化：**发送背压与业务 ACK","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":5,"sourceQuestion":3,"sourceRoundTitle":"TIME_WAIT、CLOSE_WAIT 与半关闭","originalQuestionHeading":"节点大量 CLOSE_WAIT，同时在线人数下降，首先查什么？"},{"id":"daily-2026-10-10-r05-q04","module":"TCP/HTTP","type":"代码题","title":"实现一次性关闭状态机，区分读 EOF、待发送数据和最终关闭。","prompt":"实现一次性关闭状态机，区分读 EOF、待发送数据和最终关闭。","promptMarkdown":"实现一次性关闭状态机，区分读 EOF、待发送数据和最终关闭。","answer":["见代码；读 EOF 后如待发送未清零则继续等待，清零后进入 closed。"],"pitfalls":["FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。"],"follow":"发送背压与业务 ACK","answerMarkdown":"见代码；读 EOF 后如待发送未清零则继续等待，清零后进入 closed。\n\n**易错点：**FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。\n\n```cpp\n#include <cassert>\n#include <cstddef>\nclass Closing {\n    bool eof_=false, closed_=false; std::size_t pending_;\n    void update(){if(eof_ && pending_==0) closed_=true;}\npublic:\n    explicit Closing(std::size_t n):pending_(n){}\n    void readEof(){eof_=true; update();}\n    bool sent(std::size_t n){if(n>pending_ || closed_) return false; pending_-=n; update(); return true;}\n    bool closed() const{return closed_;}\n};\nint main(){\n    Closing c(3); c.readEof(); assert(!c.closed());\n    assert(c.sent(2)); assert(!c.closed()); assert(c.sent(1)); assert(c.closed());\n    assert(!c.sent(1)); Closing empty(0); empty.readEof(); assert(empty.closed());\n}\n```\n\n**复杂度与边界：**时间/空间 O(1)，只模拟应用状态；无真实 TCP、超时、错误或丢弃策略。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**发送背压与业务 ACK","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":5,"sourceQuestion":4,"sourceRoundTitle":"TIME_WAIT、CLOSE_WAIT 与半关闭","originalQuestionHeading":"实现一次性关闭状态机，区分读 EOF、待发送数据和最终关闭。"},{"id":"daily-2026-10-10-r05-q05","module":"项目追问","type":"场景题","title":"IM 断线时如何处理未发完消息与新会话接管？","prompt":"IM 断线时如何处理未发完消息与新会话接管？","promptMarkdown":"IM 断线时如何处理未发完消息与新会话接管？","answer":["建议按协议决定发送清理窗口，设置截止时间；消息可靠性回到持久记录与业务 ACK，路由删除按旧会话条件进行，新连接重新鉴权。"],"pitfalls":["FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。"],"follow":"发送背压与业务 ACK","answerMarkdown":"建议按协议决定发送清理窗口，设置截止时间；消息可靠性回到持久记录与业务 ACK，路由删除按旧会话条件进行，新连接重新鉴权。\n\n**易错点：**FIN 不是双方立即都不能发；CLOSE_WAIT 通常需要应用处理。\n\n**下一轮强化：**发送背压与业务 ACK","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":5,"sourceQuestion":5,"sourceRoundTitle":"TIME_WAIT、CLOSE_WAIT 与半关闭","originalQuestionHeading":"IM 断线时如何处理未发完消息与新会话接管？"},{"id":"daily-2026-10-10-r06-q01","module":"TCP/HTTP","type":"概念题","title":"TLS 提供哪些保证，证书只检查有效期够吗？","prompt":"TLS 提供哪些保证，证书只检查有效期够吗？","promptMarkdown":"TLS 提供哪些保证，证书只检查有效期够吗？","answer":["TLS 提供传输机密性、完整性与相应身份认证；还要验证可信链、目标身份、用途和策略。加密连接本身不能证明连接到正确服务。"],"pitfalls":["SNI 不是信任证明；不要为了连接成功禁用验证。"],"follow":"代理隧道与 TLS 错误证据","answerMarkdown":"TLS 提供传输机密性、完整性与相应身份认证；还要验证可信链、目标身份、用途和策略。加密连接本身不能证明连接到正确服务。\n\n**易错点：**SNI 不是信任证明；不要为了连接成功禁用验证。\n\n**下一轮强化：**代理隧道与 TLS 错误证据","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":6,"sourceQuestion":1,"sourceRoundTitle":"TLS 身份校验与失败分类","originalQuestionHeading":"TLS 提供哪些保证，证书只检查有效期够吗？"},{"id":"daily-2026-10-10-r06-q02","module":"TCP/HTTP","type":"概念题","title":"证书链、主机名与 SNI 分别解决什么问题？","prompt":"证书链、主机名与 SNI 分别解决什么问题？","promptMarkdown":"证书链、主机名与 SNI 分别解决什么问题？","answer":["信任链建立证书可信关系，主机名校验将证书与目标身份关联，SNI 在握手中帮助服务端选择配置；SNI 不代替证书身份检查。"],"pitfalls":["SNI 不是信任证明；不要为了连接成功禁用验证。"],"follow":"代理隧道与 TLS 错误证据","answerMarkdown":"信任链建立证书可信关系，主机名校验将证书与目标身份关联，SNI 在握手中帮助服务端选择配置；SNI 不代替证书身份检查。\n\n**易错点：**SNI 不是信任证明；不要为了连接成功禁用验证。\n\n**下一轮强化：**代理隧道与 TLS 错误证据","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":6,"sourceQuestion":2,"sourceRoundTitle":"TLS 身份校验与失败分类","originalQuestionHeading":"证书链、主机名与 SNI 分别解决什么问题？"},{"id":"daily-2026-10-10-r06-q03","module":"TCP/HTTP","type":"场景题","title":"浏览器能访问而 C++ 客户端 TLS 失败，应怎样分层排查？","prompt":"浏览器能访问而 C++ 客户端 TLS 失败，应怎样分层排查？","promptMarkdown":"浏览器能访问而 C++ 客户端 TLS 失败，应怎样分层排查？","answer":["依次检查 DNS、TCP、代理、握手、信任库、系统时间、服务端链与目标主机名；比较实际端点和代理环境，不能直接关闭证书验证。"],"pitfalls":["SNI 不是信任证明；不要为了连接成功禁用验证。"],"follow":"代理隧道与 TLS 错误证据","answerMarkdown":"依次检查 DNS、TCP、代理、握手、信任库、系统时间、服务端链与目标主机名；比较实际端点和代理环境，不能直接关闭证书验证。\n\n**易错点：**SNI 不是信任证明；不要为了连接成功禁用验证。\n\n**下一轮强化：**代理隧道与 TLS 错误证据","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":6,"sourceQuestion":3,"sourceRoundTitle":"TLS 身份校验与失败分类","originalQuestionHeading":"浏览器能访问而 C++ 客户端 TLS 失败，应怎样分层排查？"},{"id":"daily-2026-10-10-r06-q04","module":"TCP/HTTP","type":"代码题","title":"实现证书检查结果的策略组合，任一必要条件失败就拒绝。","prompt":"实现证书检查结果的策略组合，任一必要条件失败就拒绝。","promptMarkdown":"实现证书检查结果的策略组合，任一必要条件失败就拒绝。","answer":["见代码；输入布尔值来自可信 TLS 库的真实校验，函数本身不解析证书。"],"pitfalls":["SNI 不是信任证明；不要为了连接成功禁用验证。"],"follow":"代理隧道与 TLS 错误证据","answerMarkdown":"见代码；输入布尔值来自可信 TLS 库的真实校验，函数本身不解析证书。\n\n**易错点：**SNI 不是信任证明；不要为了连接成功禁用验证。\n\n```cpp\n#include <cassert>\nstruct Checks {bool trusted, hostname, time, purpose;};\nbool accept(Checks c){return c.trusted && c.hostname && c.time && c.purpose;}\nint main(){\n    assert(accept({true,true,true,true}));\n    assert(!accept({true,false,true,true}));\n    assert(!accept({false,true,true,true}));\n    assert(!accept({true,true,false,true}));\n    assert(!accept({true,true,true,false}));\n}\n```\n\n**复杂度与边界：**时间/空间 O(1)，这是校验结果策略模型，不是 TLS 验证器；实际使用成熟库的验证 API。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**代理隧道与 TLS 错误证据","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":6,"sourceQuestion":4,"sourceRoundTitle":"TLS 身份校验与失败分类","originalQuestionHeading":"实现证书检查结果的策略组合，任一必要条件失败就拒绝。"},{"id":"daily-2026-10-10-r06-q05","module":"项目追问","type":"场景题","title":"IM WebSocket 从 ws 改为 wss 后，还需要哪些鉴权？","prompt":"IM WebSocket 从 ws 改为 wss 后，还需要哪些鉴权？","promptMarkdown":"IM WebSocket 从 ws 改为 wss 后，还需要哪些鉴权？","answer":["建议仍校验 Token、撤销状态、会话权限、消息权限与连接 Origin 策略；TLS 只保护通道，不消除越权、重放业务操作或服务器存储风险。"],"pitfalls":["SNI 不是信任证明；不要为了连接成功禁用验证。"],"follow":"代理隧道与 TLS 错误证据","answerMarkdown":"建议仍校验 Token、撤销状态、会话权限、消息权限与连接 Origin 策略；TLS 只保护通道，不消除越权、重放业务操作或服务器存储风险。\n\n**易错点：**SNI 不是信任证明；不要为了连接成功禁用验证。\n\n**下一轮强化：**代理隧道与 TLS 错误证据","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":6,"sourceQuestion":5,"sourceRoundTitle":"TLS 身份校验与失败分类","originalQuestionHeading":"IM WebSocket 从 ws 改为 wss 后，还需要哪些鉴权？"},{"id":"daily-2026-10-10-r07-q01","module":"MySQL","type":"概念题","title":"记录锁、gap lock、next-key lock 各锁什么？","prompt":"记录锁、gap lock、next-key lock 各锁什么？","promptMarkdown":"记录锁、gap lock、next-key lock 各锁什么？","answer":["记录锁锁索引记录；gap lock 约束索引间隙插入；next-key lock 组合记录与其前间隙。实际类型取决于隔离级别、索引和查询条件，不能宣称所有查询都加这些锁。"],"pitfalls":["锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。"],"follow":"死锁与锁等待超时的回滚边界","answerMarkdown":"记录锁锁索引记录；gap lock 约束索引间隙插入；next-key lock 组合记录与其前间隙。实际类型取决于隔离级别、索引和查询条件，不能宣称所有查询都加这些锁。\n\n**易错点：**锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。\n\n**下一轮强化：**死锁与锁等待超时的回滚边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":7,"sourceQuestion":1,"sourceRoundTitle":"InnoDB 锁范围与死锁","originalQuestionHeading":"记录锁、gap lock、next-key lock 各锁什么？"},{"id":"daily-2026-10-10-r07-q02","module":"MySQL","type":"概念题","title":"没有合适索引为什么可能扩大锁范围？","prompt":"没有合适索引为什么可能扩大锁范围？","promptMarkdown":"没有合适索引为什么可能扩大锁范围？","answer":["锁范围与扫描路径有关，缺少可定位索引可能扫描并锁更多记录；普通一致性读与锁定读语义不同。应结合执行计划与实际锁观测。"],"pitfalls":["锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。"],"follow":"死锁与锁等待超时的回滚边界","answerMarkdown":"锁范围与扫描路径有关，缺少可定位索引可能扫描并锁更多记录；普通一致性读与锁定读语义不同。应结合执行计划与实际锁观测。\n\n**易错点：**锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。\n\n**下一轮强化：**死锁与锁等待超时的回滚边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":7,"sourceQuestion":2,"sourceRoundTitle":"InnoDB 锁范围与死锁","originalQuestionHeading":"没有合适索引为什么可能扩大锁范围？"},{"id":"daily-2026-10-10-r07-q03","module":"MySQL","type":"场景题","title":"两个转账事务按相反顺序锁 A、B，如何定位和安全重试？","prompt":"两个转账事务按相反顺序锁 A、B，如何定位和安全重试？","promptMarkdown":"两个转账事务按相反顺序锁 A、B，如何定位和安全重试？","answer":["收集 deadlock 日志与事务语句顺序，统一按账户 ID 加锁，缩短事务；受害事务需完整重试，受次数、原 deadline、退避与幂等约束。不要只重试最后一条 SQL。"],"pitfalls":["锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。"],"follow":"死锁与锁等待超时的回滚边界","answerMarkdown":"收集 deadlock 日志与事务语句顺序，统一按账户 ID 加锁，缩短事务；受害事务需完整重试，受次数、原 deadline、退避与幂等约束。不要只重试最后一条 SQL。\n\n**易错点：**锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。\n\n**下一轮强化：**死锁与锁等待超时的回滚边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":7,"sourceQuestion":3,"sourceRoundTitle":"InnoDB 锁范围与死锁","originalQuestionHeading":"两个转账事务按相反顺序锁 A、B，如何定位和安全重试？"},{"id":"daily-2026-10-10-r07-q04","module":"MySQL","type":"代码题","title":"把一批账户 ID 排序去重，生成统一加锁顺序。","prompt":"把一批账户 ID 排序去重，生成统一加锁顺序。","promptMarkdown":"把一批账户 ID 排序去重，生成统一加锁顺序。","answer":["见代码；只是产生顺序，不执行数据库锁。"],"pitfalls":["锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。"],"follow":"死锁与锁等待超时的回滚边界","answerMarkdown":"见代码；只是产生顺序，不执行数据库锁。\n\n**易错点：**锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。\n\n```cpp\n#include <algorithm>\n#include <cassert>\n#include <vector>\nstd::vector<int> lockOrder(std::vector<int> ids){\n    std::sort(ids.begin(),ids.end());\n    ids.erase(std::unique(ids.begin(),ids.end()),ids.end());\n    return ids;\n}\nint main(){\n    assert((lockOrder({9,2,9,1})==std::vector<int>{1,2,9}));\n    assert(lockOrder({}).empty());\n}\n```\n\n**复杂度与边界：**排序 O(N log N)，按值输入占用 O(N) 空间；数据库事务重试另行实现。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**死锁与锁等待超时的回滚边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":7,"sourceQuestion":4,"sourceRoundTitle":"InnoDB 锁范围与死锁","originalQuestionHeading":"把一批账户 ID 排序去重，生成统一加锁顺序。"},{"id":"daily-2026-10-10-r07-q05","module":"项目追问","type":"场景题","title":"IM 更新消息、未读数和会话摘要如何统一事务锁顺序？","prompt":"IM 更新消息、未读数和会话摘要如何统一事务锁顺序？","promptMarkdown":"IM 更新消息、未读数和会话摘要如何统一事务锁顺序？","answer":["建议定义跨业务的表与键顺序，批量更新也保持相同规则。外部通知移到提交后或 Outbox；索引、外键、触发器仍可能引入额外锁，需要测试。"],"pitfalls":["锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。"],"follow":"死锁与锁等待超时的回滚边界","answerMarkdown":"建议定义跨业务的表与键顺序，批量更新也保持相同规则。外部通知移到提交后或 Outbox；索引、外键、触发器仍可能引入额外锁，需要测试。\n\n**易错点：**锁的是索引结构，不只抽象业务行；排序降低风险但不保证无死锁。\n\n**下一轮强化：**死锁与锁等待超时的回滚边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":7,"sourceQuestion":5,"sourceRoundTitle":"InnoDB 锁范围与死锁","originalQuestionHeading":"IM 更新消息、未读数和会话摘要如何统一事务锁顺序？"},{"id":"daily-2026-10-10-r08-q01","module":"MySQL","type":"概念题","title":"RC 与 RR 的普通 SELECT 快照何时建立？","prompt":"RC 与 RR 的普通 SELECT 快照何时建立？","promptMarkdown":"RC 与 RR 的普通 SELECT 快照何时建立？","answer":["RC 的一致性读通常每条语句建立新快照；RR 通常在第一次一致性读建立并复用事务快照，特定显式事务选项有额外语义。事务开始不一定已经建立普通读快照。"],"pitfalls":["普通快照读不能代替约束；检查和修改必须共同原子。"],"follow":"唯一约束与结果未知的幂等恢复","answerMarkdown":"RC 的一致性读通常每条语句建立新快照；RR 通常在第一次一致性读建立并复用事务快照，特定显式事务选项有额外语义。事务开始不一定已经建立普通读快照。\n\n**易错点：**普通快照读不能代替约束；检查和修改必须共同原子。\n\n**下一轮强化：**唯一约束与结果未知的幂等恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":8,"sourceQuestion":1,"sourceRoundTitle":"MVCC、快照读与业务条件更新","originalQuestionHeading":"RC 与 RR 的普通 SELECT 快照何时建立？"},{"id":"daily-2026-10-10-r08-q02","module":"MySQL","type":"概念题","title":"SELECT FOR UPDATE 是否直接读取旧历史快照？","prompt":"SELECT FOR UPDATE 是否直接读取旧历史快照？","promptMarkdown":"SELECT FOR UPDATE 是否直接读取旧历史快照？","answer":["锁定读使用需要加锁的当前读语义，不能简单理解为读取普通 SELECT 的历史快照；会等待并发锁，并受隔离级别与范围影响。"],"pitfalls":["普通快照读不能代替约束；检查和修改必须共同原子。"],"follow":"唯一约束与结果未知的幂等恢复","answerMarkdown":"锁定读使用需要加锁的当前读语义，不能简单理解为读取普通 SELECT 的历史快照；会等待并发锁，并受隔离级别与范围影响。\n\n**易错点：**普通快照读不能代替约束；检查和修改必须共同原子。\n\n**下一轮强化：**唯一约束与结果未知的幂等恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":8,"sourceQuestion":2,"sourceRoundTitle":"MVCC、快照读与业务条件更新","originalQuestionHeading":"SELECT FOR UPDATE 是否直接读取旧历史快照？"},{"id":"daily-2026-10-10-r08-q03","module":"MySQL","type":"场景题","title":"两个节点先查询剩余名额再更新，为什么会超卖？","prompt":"两个节点先查询剩余名额再更新，为什么会超卖？","promptMarkdown":"两个节点先查询剩余名额再更新，为什么会超卖？","answer":["读取与更新之间可被并发修改，快照隔离不自动保证业务不变量。建议原子条件更新、适当锁定或唯一约束，并检查受影响行数。"],"pitfalls":["普通快照读不能代替约束；检查和修改必须共同原子。"],"follow":"唯一约束与结果未知的幂等恢复","answerMarkdown":"读取与更新之间可被并发修改，快照隔离不自动保证业务不变量。建议原子条件更新、适当锁定或唯一约束，并检查受影响行数。\n\n**易错点：**普通快照读不能代替约束；检查和修改必须共同原子。\n\n**下一轮强化：**唯一约束与结果未知的幂等恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":8,"sourceQuestion":3,"sourceRoundTitle":"MVCC、快照读与业务条件更新","originalQuestionHeading":"两个节点先查询剩余名额再更新，为什么会超卖？"},{"id":"daily-2026-10-10-r08-q04","module":"MySQL","type":"代码题","title":"实现 mutex 保护的条件扣减：库存不足时拒绝。","prompt":"实现 mutex 保护的条件扣减：库存不足时拒绝。","promptMarkdown":"实现 mutex 保护的条件扣减：库存不足时拒绝。","answer":["见代码；检查与修改在同一临界区。"],"pitfalls":["普通快照读不能代替约束；检查和修改必须共同原子。"],"follow":"唯一约束与结果未知的幂等恢复","answerMarkdown":"见代码；检查与修改在同一临界区。\n\n**易错点：**普通快照读不能代替约束；检查和修改必须共同原子。\n\n```cpp\n#include <cassert>\n#include <mutex>\n#include <stdexcept>\nclass Stock {\n    std::mutex m_; int n_;\npublic:\n    explicit Stock(int n):n_(n){if(n<0) throw std::invalid_argument(\"negative\");}\n    bool take(int n){\n        if(n<=0) return false;\n        std::lock_guard<std::mutex> lock(m_);\n        if(n>n_) return false;\n        n_-=n; return true;\n    }\n};\nint main(){Stock s(2); assert(s.take(1)); assert(!s.take(2)); assert(s.take(1)); assert(!s.take(1)); assert(!s.take(0));}\n\n```\n\n**复杂度与边界：**单次 O(1)，锁等待另计；不是 MySQL 事务实现。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**唯一约束与结果未知的幂等恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":8,"sourceQuestion":4,"sourceRoundTitle":"MVCC、快照读与业务条件更新","originalQuestionHeading":"实现 mutex 保护的条件扣减：库存不足时拒绝。"},{"id":"daily-2026-10-10-r08-q05","module":"项目追问","type":"场景题","title":"IM 未读数或计数更新怎样避免读后写覆盖？","prompt":"IM 未读数或计数更新怎样避免读后写覆盖？","promptMarkdown":"IM 未读数或计数更新怎样避免读后写覆盖？","answer":["建议 SQL 使用原子增减或带版本条件的更新，明确计数下界；并将相关消息事实与计数保持在事务边界内。重试应防重复累加，不能仅做缓存 ++。"],"pitfalls":["普通快照读不能代替约束；检查和修改必须共同原子。"],"follow":"唯一约束与结果未知的幂等恢复","answerMarkdown":"建议 SQL 使用原子增减或带版本条件的更新，明确计数下界；并将相关消息事实与计数保持在事务边界内。重试应防重复累加，不能仅做缓存 ++。\n\n**易错点：**普通快照读不能代替约束；检查和修改必须共同原子。\n\n**下一轮强化：**唯一约束与结果未知的幂等恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":8,"sourceQuestion":5,"sourceRoundTitle":"MVCC、快照读与业务条件更新","originalQuestionHeading":"IM 未读数或计数更新怎样避免读后写覆盖？"},{"id":"daily-2026-10-10-r09-q01","module":"Redis","type":"概念题","title":"SETNX 再 EXPIRE 为什么有故障窗口？","prompt":"SETNX 再 EXPIRE 为什么有故障窗口？","promptMarkdown":"SETNX 再 EXPIRE 为什么有故障窗口？","answer":["两条命令之间进程可能崩溃，留下无 TTL 锁；用 SET key token NX PX ttl 原子设置条件与过期。TTL 单位、合法值和返回结果都需明确。"],"pitfalls":["随机 owner token 与单调 fencing token 不是同一种用途。"],"follow":"Sentinel 切换与写结果未知","answerMarkdown":"两条命令之间进程可能崩溃，留下无 TTL 锁；用 SET key token NX PX ttl 原子设置条件与过期。TTL 单位、合法值和返回结果都需明确。\n\n**易错点：**随机 owner token 与单调 fencing token 不是同一种用途。\n\n**下一轮强化：**Sentinel 切换与写结果未知","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":9,"sourceQuestion":1,"sourceRoundTitle":"Redis 原子加锁与条件解锁","originalQuestionHeading":"SETNX 再 EXPIRE 为什么有故障窗口？"},{"id":"daily-2026-10-10-r09-q02","module":"Redis","type":"概念题","title":"解锁为什么不能无条件 DEL？","prompt":"解锁为什么不能无条件 DEL？","promptMarkdown":"解锁为什么不能无条件 DEL？","answer":["锁可能已过期并被他人重建，应原子比较 owner token 后删除，常用短 Lua 脚本实现；GET 后再 DEL 仍有竞态。"],"pitfalls":["随机 owner token 与单调 fencing token 不是同一种用途。"],"follow":"Sentinel 切换与写结果未知","answerMarkdown":"锁可能已过期并被他人重建，应原子比较 owner token 后删除，常用短 Lua 脚本实现；GET 后再 DEL 仍有竞态。\n\n**易错点：**随机 owner token 与单调 fencing token 不是同一种用途。\n\n**下一轮强化：**Sentinel 切换与写结果未知","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":9,"sourceQuestion":2,"sourceRoundTitle":"Redis 原子加锁与条件解锁","originalQuestionHeading":"解锁为什么不能无条件 DEL？"},{"id":"daily-2026-10-10-r09-q03","module":"Redis","type":"场景题","title":"A 锁过期后 B 获锁，A 恢复删除 B 的锁，如何防止？","prompt":"A 锁过期后 B 获锁，A 恢复删除 B 的锁，如何防止？","promptMarkdown":"A 锁过期后 B 获锁，A 恢复删除 B 的锁，如何防止？","answer":["记录 token、租期、暂停与删除时序；条件删除解决误解锁，但旧业务写还需资源侧约束，不能只修 DEL 就宣称所有副作用安全。"],"pitfalls":["随机 owner token 与单调 fencing token 不是同一种用途。"],"follow":"Sentinel 切换与写结果未知","answerMarkdown":"记录 token、租期、暂停与删除时序；条件删除解决误解锁，但旧业务写还需资源侧约束，不能只修 DEL 就宣称所有副作用安全。\n\n**易错点：**随机 owner token 与单调 fencing token 不是同一种用途。\n\n**下一轮强化：**Sentinel 切换与写结果未知","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":9,"sourceQuestion":3,"sourceRoundTitle":"Redis 原子加锁与条件解锁","originalQuestionHeading":"A 锁过期后 B 获锁，A 恢复删除 B 的锁，如何防止？"},{"id":"daily-2026-10-10-r09-q04","module":"Redis","type":"代码题","title":"实现所有者条件解锁模型：只有 token 匹配才移除。","prompt":"实现所有者条件解锁模型：只有 token 匹配才移除。","promptMarkdown":"实现所有者条件解锁模型：只有 token 匹配才移除。","answer":["见代码；mutex 模拟单个原子操作，无 Redis、TTL 或网络。"],"pitfalls":["随机 owner token 与单调 fencing token 不是同一种用途。"],"follow":"Sentinel 切换与写结果未知","answerMarkdown":"见代码；mutex 模拟单个原子操作，无 Redis、TTL 或网络。\n\n**易错点：**随机 owner token 与单调 fencing token 不是同一种用途。\n\n```cpp\n#include <cassert>\n#include <mutex>\n#include <optional>\n#include <string>\nclass Lock {\n    std::mutex m_; std::optional<std::string> owner_;\npublic:\n    bool acquire(const std::string& token){\n        std::lock_guard<std::mutex> guard(m_);\n        if(owner_ || token.empty()) return false;\n        owner_=token; return true;\n    }\n    bool release(const std::string& token){\n        std::lock_guard<std::mutex> guard(m_);\n        if(!owner_ || *owner_!=token) return false;\n        owner_.reset(); return true;\n    }\n};\nint main(){Lock l; assert(l.acquire(\"A\")); assert(!l.release(\"B\")); assert(l.release(\"A\")); assert(l.acquire(\"B\")); assert(!l.release(\"A\"));}\n\n```\n\n**复杂度与边界：**O(L) 字符串比较/复制，空间 O(L)，锁等待另计。未实现租约与分布式安全。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**Sentinel 切换与写结果未知","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":9,"sourceQuestion":4,"sourceRoundTitle":"Redis 原子加锁与条件解锁","originalQuestionHeading":"实现所有者条件解锁模型：只有 token 匹配才移除。"},{"id":"daily-2026-10-10-r09-q05","module":"项目追问","type":"场景题","title":"Redis 锁能否保证旧持有者不会继续写 MySQL？","prompt":"Redis 锁能否保证旧持有者不会继续写 MySQL？","promptMarkdown":"Redis 锁能否保证旧持有者不会继续写 MySQL？","answer":["不能；旧持有者可在暂停后继续执行。建议 MySQL 条件状态、持久任务租约、幂等或资源侧 fencing，并确保 token 的单调性与故障恢复语义。"],"pitfalls":["随机 owner token 与单调 fencing token 不是同一种用途。"],"follow":"Sentinel 切换与写结果未知","answerMarkdown":"不能；旧持有者可在暂停后继续执行。建议 MySQL 条件状态、持久任务租约、幂等或资源侧 fencing，并确保 token 的单调性与故障恢复语义。\n\n**易错点：**随机 owner token 与单调 fencing token 不是同一种用途。\n\n**下一轮强化：**Sentinel 切换与写结果未知","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":9,"sourceQuestion":5,"sourceRoundTitle":"Redis 原子加锁与条件解锁","originalQuestionHeading":"Redis 锁能否保证旧持有者不会继续写 MySQL？"},{"id":"daily-2026-10-10-r10-q01","module":"Redis","type":"概念题","title":"Sentinel 与 Cluster 的职责有何区别？","prompt":"Sentinel 与 Cluster 的职责有何区别？","promptMarkdown":"Sentinel 与 Cluster 的职责有何区别？","answer":["Sentinel 提供监控、故障转移和主节点发现；Cluster 还涉及分片与槽路由。客户端需要实现对应协议，不能把 MOVED 与 Sentinel 发现混用。"],"pitfalls":["切换完成不等于命令成功与通知恢复；恢复必须重新验证。"],"follow":"恢复退避与重连预算","answerMarkdown":"Sentinel 提供监控、故障转移和主节点发现；Cluster 还涉及分片与槽路由。客户端需要实现对应协议，不能把 MOVED 与 Sentinel 发现混用。\n\n**易错点：**切换完成不等于命令成功与通知恢复；恢复必须重新验证。\n\n**下一轮强化：**恢复退避与重连预算","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":10,"sourceQuestion":1,"sourceRoundTitle":"Sentinel 切换与缓存恢复","originalQuestionHeading":"Sentinel 与 Cluster 的职责有何区别？"},{"id":"daily-2026-10-10-r10-q02","module":"Redis","type":"概念题","title":"已返回 OK 的写入与切换期间 Pub/Sub 通知是否绝不丢失？","prompt":"已返回 OK 的写入与切换期间 Pub/Sub 通知是否绝不丢失？","promptMarkdown":"已返回 OK 的写入与切换期间 Pub/Sub 通知是否绝不丢失？","answer":["异步复制可能丢失已确认写；Pub/Sub 至多一次，断线通知不重放。故障转移完成不等于全部业务数据无损。"],"pitfalls":["切换完成不等于命令成功与通知恢复；恢复必须重新验证。"],"follow":"恢复退避与重连预算","answerMarkdown":"异步复制可能丢失已确认写；Pub/Sub 至多一次，断线通知不重放。故障转移完成不等于全部业务数据无损。\n\n**易错点：**切换完成不等于命令成功与通知恢复；恢复必须重新验证。\n\n**下一轮强化：**恢复退避与重连预算","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":10,"sourceQuestion":2,"sourceRoundTitle":"Sentinel 切换与缓存恢复","originalQuestionHeading":"已返回 OK 的写入与切换期间 Pub/Sub 通知是否绝不丢失？"},{"id":"daily-2026-10-10-r10-q03","module":"Redis","type":"场景题","title":"切换后 IM 仍连旧主，路由错乱、通知缺失，如何恢复？","prompt":"切换后 IM 仍连旧主，路由错乱、通知缺失，如何恢复？","promptMarkdown":"切换后 IM 仍连旧主，路由错乱、通知缺失，如何恢复？","answer":["重新发现并验证主节点角色，建立连接和恢复订阅；从持久消息与 ACK 补拉，条件重建会话路由，限制重连风暴，检查缓存旧状态。未知结果写命令需按幂等语义决定重试。"],"pitfalls":["切换完成不等于命令成功与通知恢复；恢复必须重新验证。"],"follow":"恢复退避与重连预算","answerMarkdown":"重新发现并验证主节点角色，建立连接和恢复订阅；从持久消息与 ACK 补拉，条件重建会话路由，限制重连风暴，检查缓存旧状态。未知结果写命令需按幂等语义决定重试。\n\n**易错点：**切换完成不等于命令成功与通知恢复；恢复必须重新验证。\n\n**下一轮强化：**恢复退避与重连预算","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":10,"sourceQuestion":3,"sourceRoundTitle":"Sentinel 切换与缓存恢复","originalQuestionHeading":"切换后 IM 仍连旧主，路由错乱、通知缺失，如何恢复？"},{"id":"daily-2026-10-10-r10-q04","module":"Redis","type":"代码题","title":"实现故障标志组合：只要主地址、角色或订阅不满足，就要求恢复。","prompt":"实现故障标志组合：只要主地址、角色或订阅不满足，就要求恢复。","promptMarkdown":"实现故障标志组合：只要主地址、角色或订阅不满足，就要求恢复。","answer":["见代码；只是恢复触发条件，实际还要执行恢复并确认新状态。"],"pitfalls":["切换完成不等于命令成功与通知恢复；恢复必须重新验证。"],"follow":"恢复退避与重连预算","answerMarkdown":"见代码；只是恢复触发条件，实际还要执行恢复并确认新状态。\n\n**易错点：**切换完成不等于命令成功与通知恢复；恢复必须重新验证。\n\n```cpp\n#include <cassert>\nstruct Health { bool discovered, primary, subscribed; };\nbool needsRecovery(Health h){return !h.discovered || !h.primary || !h.subscribed;}\nint main(){\n    assert(!needsRecovery({true,true,true}));\n    assert(needsRecovery({false,true,true}));\n    assert(needsRecovery({true,false,true}));\n    assert(needsRecovery({true,true,false}));\n}\n```\n\n**复杂度与边界：**时间/空间 O(1)，教学判定模型；不涉及 Sentinel 网络或认证策略实现。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**恢复退避与重连预算","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":10,"sourceQuestion":4,"sourceRoundTitle":"Sentinel 切换与缓存恢复","originalQuestionHeading":"实现故障标志组合：只要主地址、角色或订阅不满足，就要求恢复。"},{"id":"daily-2026-10-10-r10-q05","module":"项目追问","type":"场景题","title":"Token 撤销与在线路由的恢复策略为什么不同？","prompt":"Token 撤销与在线路由的恢复策略为什么不同？","promptMarkdown":"Token 撤销与在线路由的恢复策略为什么不同？","answer":["撤销涉及权限，严格要求应由明确持久性和一致性约束的权威事实决定；路由属于可重建租约状态，缺失可重连恢复。缓存或 TTL 不自动保证立即撤销。"],"pitfalls":["切换完成不等于命令成功与通知恢复；恢复必须重新验证。"],"follow":"恢复退避与重连预算","answerMarkdown":"撤销涉及权限，严格要求应由明确持久性和一致性约束的权威事实决定；路由属于可重建租约状态，缺失可重连恢复。缓存或 TTL 不自动保证立即撤销。\n\n**易错点：**切换完成不等于命令成功与通知恢复；恢复必须重新验证。\n\n**下一轮强化：**恢复退避与重连预算","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":10,"sourceQuestion":5,"sourceRoundTitle":"Sentinel 切换与缓存恢复","originalQuestionHeading":"Token 撤销与在线路由的恢复策略为什么不同？"},{"id":"daily-2026-10-10-r11-q01","module":"Nginx","type":"概念题","title":"A 上已建立的 WebSocket 能否透明切换到 B？","prompt":"A 上已建立的 WebSocket 能否透明切换到 B？","promptMarkdown":"A 上已建立的 WebSocket 能否透明切换到 B？","answer":["不能由普通反向代理把已建立 WebSocket 的 TCP 与应用状态透明迁移；客户端需要重连，并重建认证、订阅和消息进度。"],"pitfalls":["新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。"],"follow":"长连接 drain 与消息恢复","answerMarkdown":"不能由普通反向代理把已建立 WebSocket 的 TCP 与应用状态透明迁移；客户端需要重连，并重建认证、订阅和消息进度。\n\n**易错点：**新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。\n\n**下一轮强化：**长连接 drain 与消息恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":11,"sourceQuestion":1,"sourceRoundTitle":"Nginx 长连接与节点摘流","originalQuestionHeading":"A 上已建立的 WebSocket 能否透明切换到 B？"},{"id":"daily-2026-10-10-r11-q02","module":"Nginx","type":"概念题","title":"upstream 负载均衡是否自动保证用户会话状态一致？","prompt":"upstream 负载均衡是否自动保证用户会话状态一致？","promptMarkdown":"upstream 负载均衡是否自动保证用户会话状态一致？","answer":["负载均衡选择连接目标，不自动复制应用内存；sticky 也不等于故障恢复。会话与消息事实应有明确外部状态与恢复协议。"],"pitfalls":["新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。"],"follow":"长连接 drain 与消息恢复","answerMarkdown":"负载均衡选择连接目标，不自动复制应用内存；sticky 也不等于故障恢复。会话与消息事实应有明确外部状态与恢复协议。\n\n**易错点：**新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。\n\n**下一轮强化：**长连接 drain 与消息恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":11,"sourceQuestion":2,"sourceRoundTitle":"Nginx 长连接与节点摘流","originalQuestionHeading":"upstream 负载均衡是否自动保证用户会话状态一致？"},{"id":"daily-2026-10-10-r11-q03","module":"Nginx","type":"场景题","title":"A 崩溃后用户重连 B，旧节点迟到回调删新路由，如何修？","prompt":"A 崩溃后用户重连 B，旧节点迟到回调删新路由，如何修？","promptMarkdown":"A 崩溃后用户重连 B，旧节点迟到回调删新路由，如何修？","answer":["旧回调必须携带旧节点与代际，Redis 删除要原子条件判断。按用户 ID 无条件 DEL 会删除新状态；Nginx 不替应用解决此竞态。"],"pitfalls":["新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。"],"follow":"长连接 drain 与消息恢复","answerMarkdown":"旧回调必须携带旧节点与代际，Redis 删除要原子条件判断。按用户 ID 无条件 DEL 会删除新状态；Nginx 不替应用解决此竞态。\n\n**易错点：**新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。\n\n**下一轮强化：**长连接 drain 与消息恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":11,"sourceQuestion":3,"sourceRoundTitle":"Nginx 长连接与节点摘流","originalQuestionHeading":"A 崩溃后用户重连 B，旧节点迟到回调删新路由，如何修？"},{"id":"daily-2026-10-10-r11-q04","module":"Nginx","type":"代码题","title":"按 node_id 和 generation 同时匹配才删除路由。","prompt":"按 node_id 和 generation 同时匹配才删除路由。","promptMarkdown":"按 node_id 和 generation 同时匹配才删除路由。","answer":["见代码；单线程路由模型。"],"pitfalls":["新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。"],"follow":"长连接 drain 与消息恢复","answerMarkdown":"见代码；单线程路由模型。\n\n**易错点：**新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。\n\n```cpp\n#include <cassert>\n#include <cstdint>\n#include <optional>\n#include <string>\nstruct Route {std::string node; std::uint64_t generation;};\nbool remove(std::optional<Route>& r,const std::string& node,std::uint64_t g){\n    if(!r || r->node!=node || r->generation!=g) return false;\n    r.reset(); return true;\n}\nint main(){\n    std::optional<Route> r=Route{\"B\",2};\n    assert(!remove(r,\"A\",1)); assert(!remove(r,\"B\",1));\n    assert(remove(r,\"B\",2)); assert(!remove(r,\"B\",2));\n}\n```\n\n**复杂度与边界：**O(L) 节点字符串比较，额外空间 O(1)。不代替 Redis 原子脚本与 TTL。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**长连接 drain 与消息恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":11,"sourceQuestion":4,"sourceRoundTitle":"Nginx 长连接与节点摘流","originalQuestionHeading":"按 node_id 和 generation 同时匹配才删除路由。"},{"id":"daily-2026-10-10-r11-q05","module":"项目追问","type":"场景题","title":"滚动发布如何让长连接用户恢复而不重复入库？","prompt":"滚动发布如何让长连接用户恢复而不重复入库？","promptMarkdown":"滚动发布如何让长连接用户恢复而不重复入库？","answer":["建议先摘新流量、拒绝新任务、等待关键事务并限时关闭长连接；客户端按稳定幂等键和 ACK 水位恢复。路由按条件注销，资源最后销毁，Outbox 未确认事件保留重试。"],"pitfalls":["新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。"],"follow":"长连接 drain 与消息恢复","answerMarkdown":"建议先摘新流量、拒绝新任务、等待关键事务并限时关闭长连接；客户端按稳定幂等键和 ACK 水位恢复。路由按条件注销，资源最后销毁，Outbox 未确认事件保留重试。\n\n**易错点：**新连接可重新负载均衡，旧连接不能靠 upstream 配置迁移。\n\n**下一轮强化：**长连接 drain 与消息恢复","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":11,"sourceQuestion":5,"sourceRoundTitle":"Nginx 长连接与节点摘流","originalQuestionHeading":"滚动发布如何让长连接用户恢复而不重复入库？"},{"id":"daily-2026-10-10-r12-q01","module":"项目追问","type":"概念题","title":"为什么多节点本地时间不能保证同会话消息顺序？","prompt":"为什么多节点本地时间不能保证同会话消息顺序？","promptMarkdown":"为什么多节点本地时间不能保证同会话消息顺序？","answer":["节点时钟偏差、相同精度、并发分配与提交交错都会影响顺序；需要明确每会话的权威排序与可见性规则，不能只按 wall clock。"],"pitfalls":["自增分配顺序不等于提交可见顺序；去重不能修复缺口。"],"follow":"用故障注入证明消息恢复边界","answerMarkdown":"节点时钟偏差、相同精度、并发分配与提交交错都会影响顺序；需要明确每会话的权威排序与可见性规则，不能只按 wall clock。\n\n**易错点：**自增分配顺序不等于提交可见顺序；去重不能修复缺口。\n\n**下一轮强化：**用故障注入证明消息恢复边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":12,"sourceQuestion":1,"sourceRoundTitle":"多节点排序、幂等与可靠性复盘","originalQuestionHeading":"为什么多节点本地时间不能保证同会话消息顺序？"},{"id":"daily-2026-10-10-r12-q02","module":"项目追问","type":"概念题","title":"顺序号、message_id、client_msg_id 和 ACK 分别承担什么职责？","prompt":"顺序号、message_id、client_msg_id 和 ACK 分别承担什么职责？","promptMarkdown":"顺序号、message_id、client_msg_id 和 ACK 分别承担什么职责？","answer":["顺序号表达规定范围内顺序，message_id 标识消息事实，client_msg_id 让重试收敛，ACK 表达客户端确认进度；四者不能无条件互相替代。"],"pitfalls":["自增分配顺序不等于提交可见顺序；去重不能修复缺口。"],"follow":"用故障注入证明消息恢复边界","answerMarkdown":"顺序号表达规定范围内顺序，message_id 标识消息事实，client_msg_id 让重试收敛，ACK 表达客户端确认进度；四者不能无条件互相替代。\n\n**易错点：**自增分配顺序不等于提交可见顺序；去重不能修复缺口。\n\n**下一轮强化：**用故障注入证明消息恢复边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":12,"sourceQuestion":2,"sourceRoundTitle":"多节点排序、幂等与可靠性复盘","originalQuestionHeading":"顺序号、message_id、client_msg_id 和 ACK 分别承担什么职责？"},{"id":"daily-2026-10-10-r12-q03","module":"项目追问","type":"场景题","title":"两条并发消息通知乱序，客户端直接显示跳动，怎样恢复稳定顺序？","prompt":"两条并发消息通知乱序，客户端直接显示跳动，怎样恢复稳定顺序？","promptMarkdown":"两条并发消息通知乱序，客户端直接显示跳动，怎样恢复稳定顺序？","answer":["建议通知只作提示，从持久事实按既定顺序补拉；客户端对缺口等待或补拉并去重。水位必须满足约定的连续性，不能跳过尚未可见数据。"],"pitfalls":["自增分配顺序不等于提交可见顺序；去重不能修复缺口。"],"follow":"用故障注入证明消息恢复边界","answerMarkdown":"建议通知只作提示，从持久事实按既定顺序补拉；客户端对缺口等待或补拉并去重。水位必须满足约定的连续性，不能跳过尚未可见数据。\n\n**易错点：**自增分配顺序不等于提交可见顺序；去重不能修复缺口。\n\n**下一轮强化：**用故障注入证明消息恢复边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":12,"sourceQuestion":3,"sourceRoundTitle":"多节点排序、幂等与可靠性复盘","originalQuestionHeading":"两条并发消息通知乱序，客户端直接显示跳动，怎样恢复稳定顺序？"},{"id":"daily-2026-10-10-r12-q04","module":"项目追问","type":"代码题","title":"实现有限批次排序与去重：同序号同内容幂等，不同内容冲突。","prompt":"实现有限批次排序与去重：同序号同内容幂等，不同内容冲突。","promptMarkdown":"实现有限批次排序与去重：同序号同内容幂等，不同内容冲突。","answer":["见代码；排序后重复同 seq 内容相同保留一个，否则冲突。这里只处理完整批次，不假定序号连续。"],"pitfalls":["自增分配顺序不等于提交可见顺序；去重不能修复缺口。"],"follow":"用故障注入证明消息恢复边界","answerMarkdown":"见代码；排序后重复同 seq 内容相同保留一个，否则冲突。这里只处理完整批次，不假定序号连续。\n\n**易错点：**自增分配顺序不等于提交可见顺序；去重不能修复缺口。\n\n```cpp\n#include <algorithm>\n#include <cassert>\n#include <stdexcept>\n#include <string>\n#include <vector>\nstruct Message {int seq; std::string body;};\nstd::vector<Message> normalize(std::vector<Message> v){\n    std::sort(v.begin(),v.end(),[](const auto& a,const auto& b){return a.seq<b.seq;});\n    std::vector<Message> result;\n    for(const auto& m:v){\n        if(!result.empty() && result.back().seq==m.seq){\n            if(result.back().body!=m.body) throw std::logic_error(\"sequence conflict\");\n        }else result.push_back(m);\n    }\n    return result;\n}\nint main(){\n    auto v=normalize({{2,\"b\"},{1,\"a\"},{2,\"b\"}});\n    assert(v.size()==2 && v[0].seq==1 && v[1].seq==2);\n    bool bad=false; try{normalize({{1,\"a\"},{1,\"b\"}});}catch(const std::logic_error&){bad=true;}\n    assert(bad); assert(normalize({}).empty());\n}\n```\n\n**复杂度与边界：**时间 O(N log N) 加字符串成本，空间 O(N＋内容)。内存单批模型，无持久化、跨线程或缺口补拉。\n\n代码通过 C++17 严格警告编译及所附断言。\n\n**下一轮强化：**用故障注入证明消息恢复边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":12,"sourceQuestion":4,"sourceRoundTitle":"多节点排序、幂等与可靠性复盘","originalQuestionHeading":"实现有限批次排序与去重：同序号同内容幂等，不同内容冲突。"},{"id":"daily-2026-10-10-r12-q05","module":"项目追问","type":"场景题","title":"如何在面试中说明你的 IM 已实现能力与计划改进？","prompt":"如何在面试中说明你的 IM 已实现能力与计划改进？","promptMarkdown":"如何在面试中说明你的 IM 已实现能力与计划改进？","answer":["按代码或测试能证明的事实说明技术选型、业务链路与故障边界，再提出 Outbox、ACK、会话序号等建议；没有测量不要编造 QPS、零丢失或生产成效。"],"pitfalls":["自增分配顺序不等于提交可见顺序；去重不能修复缺口。"],"follow":"用故障注入证明消息恢复边界","answerMarkdown":"按代码或测试能证明的事实说明技术选型、业务链路与故障边界，再提出 Outbox、ACK、会话序号等建议；没有测量不要编造 QPS、零丢失或生产成效。\n\n**易错点：**自增分配顺序不等于提交可见顺序；去重不能修复缺口。\n\n**下一轮强化：**用故障注入证明消息恢复边界","manual":true,"priority":false,"sourceDate":"2026-10-10","sourceRound":12,"sourceQuestion":5,"sourceRoundTitle":"多节点排序、幂等与可靠性复盘","originalQuestionHeading":"如何在面试中说明你的 IM 已实现能力与计划改进？"}];const ids=new Set(window.QUESTION_BANK.map(q=>q.id));for(const q of added){if(!ids.has(q.id)){window.QUESTION_BANK.push(q);ids.add(q.id);}}})();
